static long scale_anchor(const int factor, long base) {
    const long limit = 900000;
    long result = base * factor;

    return result > limit ? limit : result;
}

int count_buffer(void) {
    static int calls;
    static const char steps[4] = { 1, 2, 3, 1 };

    calls++;

    return calls * 10 + steps[calls & 3];
}

int shared_cursor = 6;

int peek_cursor(const int *const cells, int n) {
    extern int shared_cursor;
    int sum = shared_cursor;

    for (int i = 0; i < n; i++)
        sum += cells[i];

    return sum;
}

char grade_header(unsigned char mark) {
    static const unsigned char bands[3] = { 90, 70, 50 };
    const char *letters = "ABCD";

    for (int i = 0; i < 3; i++)
        if (mark >= bands[i])
            return letters[i];

    return letters[3];
}

